rules=[]
def rule(id,c,typ,text,page,extra=None,source=N):
 act={'type':typ,'components':['osimertinib'],'message':text}
 if extra:act.update(extra)
 rules.append({'id':id,'priority':100-len(rules),'when':c,'action':act,'source':{'document':'NCCP00353 v5' if source==N else 'EMA Tagrisso product information, updated 18/08/2026','url':source,'page':str(page)},'explanation':text})
rule('ECOG_OUTSIDE_USUAL_RANGE',cond('ecog','>',1),'consultant_review','NCCP eligibility is ECOG 0–1; ECOG 2 or greater needs explicit Consultant assessment.','2')
rule('HYPERSENSITIVITY',eq('hypersensitivity'),'contraindicated','Do not administer with hypersensitivity to osimertinib or its excipients.','2')
rule('PREGNANCY_BREASTFEEDING',anyc(eq('pregnancy'),eq('breastfeeding')),'contraindicated','NCCP excludes pregnancy and breastfeeding; urgent specialist reproductive/feeding plan.','2')
rule('CONGENITAL_LONG_QT',eq('congenital_long_qt'),'contraindicated','NCCP excludes congenital long QT syndrome.','2')
rule('ST_JOHNS_WORT',eq('st_johns_wort'),'contraindicated','Concomitant St John’s wort is contraindicated. Resolve before osimertinib.','5')
rule('INDICATION_OUTSIDE_SCOPE',eq('indication_id','outside_scope'),'consultant_review','NCCP00353 v5 covers only 00353a/b/c. Post-chemoradiation LAURA and FLAURA2 chemotherapy combination require their own applicable protocol and support plan.','1–2')
rule('EGFR_NOT_CONFIRMED',eq('egfr_validated_positive',False),'consultant_review','Validated, indication-appropriate EGFR positivity must be established before treatment. A negative plasma result may require tissue testing.','2–3')
rule('T790M_NOT_CONFIRMED',allc(eq('indication_id','00353a'),eq('t790m_confirmed',False)),'consultant_review','00353a requires validated EGFR T790M positivity.','1–2')
rule('ADJUVANT_SCOPE',allc(eq('indication_id','00353c'),eq('adjuvant_complete_resection_stage_mutation',False)),'consultant_review','Confirm complete resection, stage IB–IIIA and tumour Ex19del/L858R before using the adjuvant indication.','1–2')
rule('ADJUVANT_EXCLUSIONS',allc(eq('indication_id','00353c'),eq('adjuvant_exclusion_present')),'contraindicated','NCCP adjuvant pathway excludes neoadjuvant chemotherapy, neoadjuvant/adjuvant radiation and prior EGFR inhibitor therapy; specialist protocol review is required.','2')
rule('ADJUVANT_SURGERY_WINDOW',allc(eq('indication_id','00353c'),eq('adjuvant_chemotherapy',False),cond('weeks_since_resection','>',10)),'consultant_review','Without adjuvant chemotherapy NCCP starts osimertinib within 10 weeks of complete resection.','2')
rule('ADJUVANT_CHEMO_INCOMPLETE',allc(eq('indication_id','00353c'),eq('adjuvant_chemotherapy'),eq('adjuvant_chemotherapy_completed',False)),'withhold','Do not start adjuvant osimertinib before adjuvant chemotherapy is complete. NCCP permits up to four platinum-doublet cycles.','2')
rule('ADJUVANT_CHEMO_WINDOW',allc(eq('indication_id','00353c'),eq('adjuvant_chemotherapy'),anyc(cond('weeks_since_adjuvant_chemo','<',2),cond('weeks_since_adjuvant_chemo','>',10))),'consultant_review','After adjuvant chemotherapy, start no sooner than two and no later than ten weeks after its final dose.','2')
rule('ADJUVANT_DURATION',allc(eq('indication_id','00353c'),cond('adjuvant_treatment_months','>=',36)),'consultant_review','At three years review planned completion. Treatment beyond three years was not studied; do not extrapolate the advanced continuous-duration plan.','1')
rule('ILD_SUSPECTED',anyc(eq('ild_suspected'),cond('pneumonitis_grade','>=',1)),'withhold','Interrupt osimertinib and urgently investigate possible ILD/pneumonitis. A symptom grade does not confirm the diagnosis; if confirmed use the permanent-stop pathway.','4–5')
rule('ILD_CONFIRMED',eq('ild_confirmed'),'permanently_discontinue','NCCP permanently discontinues diagnosed ILD/pneumonitis, including grade 1. EMA section 4.4 mentions individual benefit/risk consideration for reintroduction; no automatic rechallenge is encoded.','4–5')
rule('SCAR_SUSPECTED',eq('scar_suspected'),'withhold','Interrupt and urgently assess suspected SJS/TEN. Do not manage blistering or mucosal involvement as ordinary acneiform rash.','5')
rule('SCAR_CONFIRMED',eq('scar_confirmed'),'permanently_discontinue','Permanently discontinue osimertinib for confirmed SJS or TEN.','4–5')
rule('APLASTIC_SUSPECTED',eq('aplastic_anaemia_suspected'),'consultant_review','Urgent blood-count/clinical assessment; NCCP advises close monitoring and consideration of interruption or discontinuation for suspected aplastic anaemia.','5',{'dose_calculation':'specialist_review'})
rule('APLASTIC_CONFIRMED',eq('aplastic_anaemia_confirmed'),'permanently_discontinue','Permanently discontinue osimertinib for confirmed aplastic anaemia.','4–5')
rule('QTC_SINGLE_HIGH',cond('qtc_ms','>',500),'consultant_review','QTc above 500 ms needs urgent review and repeat ECG. Confirm whether >500 ms occurred on at least two separate ECGs; a single value does not establish the source restart pathway.','3–4',{'dose_calculation':'specialist_review'})
rule('QTC_CONFIRMED_HIGH',eq('qtc_second_ecg_gt500'),'withhold_then_reduce','Withhold for QTc >500 ms on at least two separate ECGs. Resume only after QTc <481 ms, or recovery to baseline if baseline ≥481 ms; source restart is 40 mg once daily, subject to Consultant authorisation.','4',{'component_changes':{'osimertinib':{'dose':{'value':40,'unit':'mg once daily'}}}})
rule('QTC_SERIOUS_ARRHYTHMIA',eq('qtc_serious_arrhythmia'),'permanently_discontinue','Permanently discontinue for QTc prolongation with signs/symptoms of serious arrhythmia, including torsade de pointes or polymorphic ventricular tachycardia.','4–5')
rule('QTC_RECOVERY_REVIEW',allc(eq('qtc_hold_episode'),anyc(cond('qtc_ms','<',481),allc(cond('baseline_qtc_ms','>=',481),eq('qtc_recovered_to_baseline')))),'consultant_review','Source QTc recovery criterion is met; Consultant must review all other limitations before authorising the 40 mg once-daily restart. No automatic clearance.','4',{'dose_calculation':'specialist_review'})
rule('QTC_BASELINE_CAUTION',cond('baseline_qtc_ms','>',470),'consultant_review','QTc >470 ms was a clinical-trial exclusion; review baseline risk, interacting drugs and electrolytes. This is not the >500 ms two-ECG treatment-hold rule.','2,5')
rule('OSIMERTINIB_LVEF',eq('lvef_change'),'consultant_review','Assess cardiac symptoms and LVEF promptly. NCCP/EMA monotherapy sources advise cardiac monitoring but do not define an automatic LVEF percentage dose-reduction rule.','2,5',{'dose_calculation':'specialist_review'})
for f,id in [('diarrhoea_grade','TARGET_DIARRHOEA_G3'),('rash_grade','TARGET_RASH_G3'),('other_toxicity_grade','OTHER_G3_HOLD')]:rule(id,cond(f,'>=',3),'withhold','Withhold osimertinib for up to three weeks for a grade ≥3 other adverse reaction. Reassess recovery to grade 0–2 and the separate serious-syndrome pathways before any restart.','4')
rule('OTHER_G3_NOT_RECOVERED',allc(eq('grade3_episode_held'),eq('toxicity_recovered_grade0_2',False),cond('toxicity_hold_days','>=',21)),'permanently_discontinue','Grade ≥3 other adverse reaction has not improved to grade 0–2 after three weeks of withholding: permanently discontinue.','4')
rule('OTHER_G3_RECOVERED',allc(eq('grade3_episode_held'),eq('toxicity_recovered_grade0_2'),cond('toxicity_hold_days','<=',21)),'consultant_review','After recovery to grade 0–2 within up to three weeks, NCCP permits either 80 mg or 40 mg once daily. Consultant chooses according to current dose, event and competing limitations; no automatic dose selection.','4',{'dose_calculation':'specialist_review'})
rule('OTHER_G3_LATE_RECOVERY',allc(eq('grade3_episode_held'),eq('toxicity_recovered_grade0_2'),cond('toxicity_hold_days','>',21)),'consultant_review','Recovery occurred after the source three-week window. The routine source restart option is not established; Consultant review without automatic restart.','4',{'dose_calculation':'specialist_review'})
rule('OF590_00353_OSI_HEP_SEV',eq('targeted_hepatic_band','severe'),'consultant_review','Severe hepatic / Child-Pugh C: NCCP says 50% of original dose may be considered, but EMA 4.2 says use is not recommended because safety/efficacy are unestablished. Reconcile with Consultant and pharmacy; do not calculate an automatic 40 mg dose.','3',{'dose_calculation':'specialist_review'})
rule('RENAL_EVIDENCE_GAP',anyc(eq('targeted_renal_band',1),cond('osimertinib_crcl_ml_min','<',15)),'consultant_review','NCCP expects no renal/dialysis adjustment, but EMA evidence is unestablished for CrCl <15 mL/min or dialysis and advises caution. Consultant/pharmacy review, not automatic clearance or percentage adjustment.','5',{'dose_calculation':'specialist_review'},S)
rule('SEVERE_RENAL_CAUTION',eq('severe_renal_impairment'),'consultant_review','EMA advises caution in severe renal impairment even though routine dose adjustment is not required. Individualise monitoring; do not import another TKI renal reduction.','5',{'dose_calculation':'specialist_review'},S)
rule('LIVER_RESULTS_CONTEXT',anyc(cond('alt_ast_uln_multiple','>',1),cond('bilirubin_uln_multiple','>',1)),'consultant_review','Abnormal liver results require baseline/trend, clinical hepatic assessment and event-specific toxicity grading. No NCCP osimertinib automatic ALT >5 × ULN hold rule is specified; do not infer drug hepatitis or Child-Pugh C from isolated results.','3–4',{'dose_calculation':'specialist_review'})
rule('STRONG_CYP3A_INDUCER',eq('strong_cyp3a_inducer'),'consultant_review','Avoid strong CYP3A inducers where possible; moderate inducers also need caution. NCCP provides no dose adjustment to overcome an interaction.','5',{'dose_calculation':'specialist_review'})
rule('QTC_MEDICINES_REVIEW',eq('qtc_prolonging_medicine'),'consultant_review','Review QT-prolonging medicines and electrolyte risk, obtain ECG/electrolytes as indicated, and choose supportive medicines individually.','5')
rule('KERATITIS_REVIEW',eq('keratitis_symptoms'),'consultant_review','Prompt ophthalmology referral for possible keratitis; assess eye symptoms rather than assign an automatic systemic dose reduction.','5')
